        for k, v in query:
            if isinstance(k, six.binary_type):
                k = quote_plus(k, safe)
            else:
                k = quote_plus(six.text_type(k), safe, encoding, errors)

            if isinstance(v, six.binary_type):
                v = quote_plus(v, safe)
            else:
                v = quote_plus(six.text_type(v), safe, encoding, errors)
            l.append(k + u'=' + v)
    else:
